package com.dlt.predictor.auth;import com.dlt.predictor.api.ApiResponse;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/v1/auth") public class AuthController{private final AuthService service;AuthController(AuthService s){service=s;}@PostMapping("/register")ApiResponse<Map<String,String>>register(@Valid @RequestBody Credentials x){service.register(x.username(),x.password());return ApiResponse.ok(Map.of("message","注册已提交，等待管理员审核"));}@PostMapping("/login")ApiResponse<Map<String,Object>>login(@Valid @RequestBody Credentials x){var a=service.login(x.username(),x.password());return ApiResponse.ok(Map.of("accessToken","dev-"+a.username(),"role",a.role().name(),"mustChangePassword",a.mustChangePassword()));}@PostMapping("/refresh")ApiResponse<Map<String,String>>refresh(){return ApiResponse.ok(Map.of("accessToken","dev-refreshed-token"));}@PostMapping("/logout")ApiResponse<Void>logout(){return ApiResponse.ok(null);}}
record Credentials(@NotBlank @Size(min=3,max=40)String username,@NotBlank @Size(min=6,max=72)String password){}
